#define RT_FILES "src/main.lar", "std/os.lar", "std/text.lar", "std/io/path.lar", "std/io/files.lar", "std/io.lar", "std/io/console.lar", "src/syntax/ast.lar", "src/semantics/types.lar", "src/semantics/linker.lar", "src/syntax/parser.lar", "src/syntax/lexer.lar", "src/editor/docstore.lar", "src/semantics/analyzer.lar", "src/semantics/expressions.lar", "src/editor/session.lar", "std/encoding/json.lar", "src/project/libraries.lar", "std/crypto.lar", "std/encoding/hex.lar", "std/encoding/toml.lar", "src/project/testing.lar", "src/project/cc.lar", "src/editor/lsp.lar", "src/editor/ide.lar", "src/editor/dap.lar", "src/codegen/gen.lar", "src/codegen/runtimeselect.lar", "src/codegen/prune.lar", "src/codegen/expressions.lar", "src/codegen/debugmap.lar", "std/os/process.lar", "std/lang.lar"
#if !defined(_WIN32) && !defined(_XOPEN_SOURCE)
#define _XOPEN_SOURCE 700
#endif
