static void lm_lm_doc_set_12000025(const char* path, const char* text) {
    int32_t i = lm_doc_find(path);
    if (i >= 0) {
        free(lm_docs[i].text);
        lm_docs[i].text = lm_doc_copy(text);
        return;
    }
    if (lm_doc_n == lm_doc_cap) {
        lm_doc_cap = lm_doc_cap ? lm_doc_cap * 2 : 16;
        lm_docs = (LmDoc*)realloc(lm_docs, sizeof(LmDoc) * (size_t)lm_doc_cap);
        if (!lm_docs) rt_panic("out of memory for the editor's documents", 0);
    }
    lm_docs[lm_doc_n].path = lm_doc_copy(path);
    lm_docs[lm_doc_n].text = lm_doc_copy(text);
    lm_doc_n++;
}
static void lm_lm_doc_remove_12000041(const char* path) {
    int32_t i = lm_doc_find(path);
    if (i < 0) return;
    free(lm_docs[i].path);
    free(lm_docs[i].text);
    lm_docs[i] = lm_docs[--lm_doc_n];
}
static bool lm_lm_doc_has_12000048(const char* path) {
    return lm_doc_find(path) >= 0;
}
static const char* lm_lm_doc_text_12000049(const char* path) {
    int32_t i = lm_doc_find(path); return i >= 0 ? lm_docs[i].text : "";
}
static int32_t lm_lm_doc_count_12000050(void) {
    return lm_doc_n;
}
static const char* lm_lm_doc_path_12000051(int32_t i) {
    return i >= 0 && i < lm_doc_n ? lm_docs[i].path : "";
}
